const route=useRoute(),router=useRouter(),loading=ref(false),worker=reactive({}); const pointRows=ref([]),rewardRows=ref([]),creditRows=ref([]),pointPage=ref(1),rewardPage=ref(1),creditPage=ref(1),pointTotal=ref(0),rewardTotal=ref(0),creditTotal=ref(0); const ps=reactive({}),rs=reactive({}),size=5
